import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

custom_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void batched_matmul_kernel(
    const float* A, const float* B_t, float* output,
    int b, int i, int j, int l, int k,
    int A_stride_b, int A_stride_i, int A_stride_j,
    int B_stride_k
) {
    extern __shared__ float A_shared[];

    int batch = blockIdx.x / (i * j);
    int residual = blockIdx.x % (i * j);
    int row = residual / j;
    int col = residual % j;

    int A_offset = batch * A_stride_b + row * A_stride_i + col * A_stride_j;

    for(int l_idx = threadIdx.x; l_idx < l; l_idx += blockDim.x) {
        A_shared[l_idx] = A[A_offset + l_idx];
    }
    __syncthreads();

    int k_idx = blockIdx.y * blockDim.x + threadIdx.x;
    if(k_idx >= k) return;

    float sum = 0.0f;
    const float* B_ptr = B_t + k_idx * B_stride_k;

    for(int l_idx = 0; l_idx < l; ++l_idx) {
        sum += A_shared[l_idx] * B_ptr[l_idx];
    }

    int out_offset = batch * i * j * k + row * j * k + col * k + k_idx;
    output[out_offset] = sum;
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B_t) {
    int b = A.size(0);
    int i = A.size(1);
    int j = A.size(2);
    int l = A.size(3);
    int k = B_t.size(0);

    auto options = torch::TensorOptions().dtype(A.dtype()).device(A.device());
    auto output = torch::zeros({b, i, j, k}, options);

    const int block_size = 256;
    dim3 grid_dim(b * i * j, (k + block_size - 1) / block_size);
    size_t shared_mem = l * sizeof(float);

    batched_matmul_kernel<<<grid_dim, block_size, shared_mem>>>(
        A.data_ptr<float>(),
        B_t.data_ptr<float>(),
        output.data_ptr<float>(),
        b, i, j, l, k,
        A.stride(0) * A.element_size(),
        A.stride(1) * A.element_size(),
        A.stride(2) * A.element_size(),
        B_t.stride(0) * B_t.element_size()
    );

    return output;
}
"""

custom_matmul_cpp = "torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B_t);"

custom_op = load_inline(
    name='custom_matmul',
    cpp_sources=custom_matmul_cpp,
    cuda_sources=custom_matmul_source,
    functions=['custom_matmul_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        B_t = B.permute(1, 0).contiguous()
        return custom_op.custom_matmul_cuda(A, B_t)
